"""Synthetic child harness: all Docker, GPU, HTTP, watcher and verifier operations are mocks."""
import atexit,importlib.util,json,subprocess,sys,threading,types
from pathlib import Path
kind,source,temp=sys.argv[1:];temp=Path(temp);cid='a'*64;image='sha256:'+'b'*64
path=Path(source)/('build_release.py' if kind=='build_timeout' else 'run_release.py')
spec=importlib.util.spec_from_file_location('control_mock',path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
m.ROOT=temp;events=[];exists=False;watcher_joined=False
class FakeProc:
 def terminate(self):events.append(['mock_clock_terminate'])
 def wait(self,timeout=None):return 0
 def kill(self):events.append(['mock_clock_kill'])
class FakeThread:
 def __init__(self,*a,**k):pass
 def start(self):events.append(['mock_watcher_start'])
 def join(self,timeout=None):
  global watcher_joined
  watcher_joined=True;events.append(['mock_watcher_join'])
class FakeSocket:
 def __enter__(self):return self
 def __exit__(self,*a):pass
 def bind(self,*a):pass
class FakeSP:
 STDOUT=subprocess.STDOUT;DEVNULL=subprocess.DEVNULL;TimeoutExpired=subprocess.TimeoutExpired
 def run(self,cmd,**kw):
  global exists
  events.append(cmd[:])
  if cmd[:2]==['docker','build']:
   Path(cmd[cmd.index('--iidfile')+1]).write_text(image);return types.SimpleNamespace(returncode=0)
  if cmd[:3]==['docker','image','inspect']:return types.SimpleNamespace(returncode=1)
  if cmd[:2] in (['docker','create'],['docker','run']):
   Path(cmd[cmd.index('--cidfile')+1]).write_text(cid);exists=True
   if kind in ('create_timeout','build_timeout','cid_inspect_timeout'):
    raise subprocess.TimeoutExpired(cmd,kw.get('timeout'))
  if cmd[:2]==['docker','inspect']:
   if kind=='cid_inspect_timeout':raise subprocess.TimeoutExpired(cmd,kw.get('timeout'))
   return types.SimpleNamespace(returncode=0 if exists else 1)
  if cmd[:2]==['docker','rm']:exists=False
  return types.SimpleNamespace(returncode=0)
 def check_output(self,cmd,**kw):
  if cmd[:2]==['docker','ps']:return ''
  return json.dumps([{'Id':image,'Config':{'Entrypoint':['vllm','serve']},'Architecture':'amd64','Os':'linux'}]).encode()
 def Popen(self,*a,**k):return FakeProc()
m.subprocess=FakeSP()
if kind=='build_timeout':
 m.OUT=temp/'build';m.OUT.mkdir()
else:
 m.CONTROL=temp/'control';m.CONTROL.mkdir();(m.CONTROL/'protected-state.json').write_text('{}')
 (temp/'clients').mkdir();(temp/'runs'/'smoke-v1').mkdir(parents=True)
 m.threading=types.SimpleNamespace(Event=threading.Event,Thread=FakeThread)
 m.socket=types.SimpleNamespace(socket=FakeSocket)
 m.wait_ready=lambda n:None
 m.capture_runtime=lambda n,p:p.write_text('{}')
 m.command=lambda *a:('owned-mock',['docker','create','--name','owned-mock'])
 verify_calls=[]
 def verify(p):
  verify_calls.append(str(p.relative_to(temp)))
  if kind=='final_verify' and len(verify_calls)==4:raise RuntimeError('deliberate final verify failure')
  p.write_text('{"passed":true,"scope":"CPU mock only"}')
 m.verify=verify
@atexit.register
def report():
 p=(m.OUT if kind=='build_timeout' else temp/'runs'/'smoke-v1')/'status.json'
 state=json.loads(p.read_text())
 clean=[e for e in events if e[:2] in (['docker','stop'],['docker','rm'])]
 checks={'status_failed':state['state']=='failed','ended_timestamp_persisted':bool(state.get('ended_utc'))}
 if kind in ('create_timeout','build_timeout'):
  checks.update(stopped_written_cid=any(e[:2]==['docker','stop'] and e[-1]==cid for e in clean),
                removed_written_cid=any(e==['docker','rm',cid] for e in clean),mock_container_no_longer_exists=not exists)
 if kind=='final_verify':checks['final_verify_failure_recorded']=state.get('service_error')=='RuntimeError'
 if kind=='cid_inspect_timeout':
  checks.update(inspect_timeout_recorded=state.get('cleanup_error')=='TimeoutExpired',
                final_service_verifier_called=verify_calls[-1]=='runs/smoke-v1/services-after.json',
                final_service_evidence_written=(temp/'runs/smoke-v1/services-after.json').exists(),
                watcher_joined=watcher_joined)
 print('CPU_MOCK_RESULT '+json.dumps({'case':kind,'passed':all(checks.values()),'checks':checks,
      'state':state,'cleanup_commands':clean,'mock_container_exists_after_case':exists,
      'verify_calls':verify_calls if kind!='build_timeout' else None}),flush=True)
if kind=='build_timeout':m.run()
else:m.run(types.SimpleNamespace(label='smoke-v1',stage='smoke',image=image,extra_env=[]))

