"""CPU-only retention/cleanup test; Docker, GPU, network and service operations are mocks."""
import atexit,hashlib,importlib.util,json,shutil,subprocess,sys,threading,types
from pathlib import Path
kind,source,temp=sys.argv[1:];source=Path(source);temp=Path(temp)
cid='a'*64;image='sha256:'+'b'*64;events=[];exists=False;running=False;created_name=None
stage='smoke' if kind=='smoke_success_cleanup' else 'measure';label=stage+'-v1'
spec=importlib.util.spec_from_file_location('control_under_cpu_test',source/'run_release.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
m.ROOT=temp;m.CONTROL=temp/'control';m.CONTROL.mkdir()
for f in source.glob('*.py'):shutil.copyfile(f,m.CONTROL/f.name)
(m.CONTROL/'protected-state.json').write_text('{}')
(temp/'clients').mkdir();shutil.copyfile(source.parent/'clients/natural_probe.py',temp/'clients/natural_probe.py')
output=temp/'runs'/label;output.mkdir(parents=True)
class FakeClock:
 def terminate(self):events.append(['mock_clock_terminate'])
 def wait(self,timeout=None):return 0
 def kill(self):events.append(['mock_clock_kill'])
class FakeThread:
 def __init__(self,*a,**kw):pass
 def start(self):events.append(['mock_watcher_start'])
 def join(self,timeout=None):events.append(['mock_watcher_join'])
class FakeSocket:
 def __enter__(self):return self
 def __exit__(self,*args):pass
 def bind(self,*args):pass
class FakeSP:
 STDOUT=subprocess.STDOUT;DEVNULL=subprocess.DEVNULL;TimeoutExpired=subprocess.TimeoutExpired
 def run(self,cmd,**kw):
  global exists,running,created_name
  events.append(list(cmd))
  if cmd[:2]==['docker','create']:
   created_name=cmd[cmd.index('--name')+1];Path(cmd[cmd.index('--cidfile')+1]).write_text(cid);exists=True
  elif cmd[:2]==['docker','start']:
   assert cmd[-1] in (created_name,cid);running=True
  elif cmd[:2]==['docker','inspect']:
   assert cmd[-1]==cid;return types.SimpleNamespace(returncode=0 if exists else 1)
  elif cmd[:2]==['docker','stop']:
   assert cmd[-1] in (created_name,cid);running=False
  elif cmd[:2]==['docker','rm']:
   assert cmd[-1] in (created_name,cid);exists=False
  elif cmd[0]==sys.executable and '--cases' in cmd:
   case=cmd[cmd.index('--cases')+1]
   if kind=='measure_client_failure_cleanup' and case=='decode':return types.SimpleNamespace(returncode=2)
  return types.SimpleNamespace(returncode=0)
 def check_output(self,cmd,**kw):
  if cmd[:2]==['docker','ps']:return ''
  return json.dumps([{'Id':image}]).encode()
 def Popen(self,*a,**kw):return FakeClock()
m.subprocess=FakeSP();m.threading=types.SimpleNamespace(Event=threading.Event,Thread=FakeThread)
m.socket=types.SimpleNamespace(socket=FakeSocket);m.wait_ready=lambda n:None
m.inspect=lambda name:{'Config':{'Cmd':['/model','--api-key','MOCK_ONLY','--served-model-name','qwen3.6-27b-fp8','--quantization','fp8']},'Mounts':[{'Destination':'/model','Source':'/mock-model'}]}
m.capture_runtime=lambda n,p:p.write_text('{"scope":"CPU mock runtime"}')
verify_calls=[]
def verify(p):
 verify_calls.append(str(p.relative_to(temp)));p.write_text('{"passed":true,"scope":"CPU mock service check"}')
m.verify=verify
@atexit.register
def report():
 state=json.loads((output/'status.json').read_text());cleanup=[c for c in events if c[:2] in (['docker','stop'],['docker','rm'])]
 client=[c for c in events if c and c[0]==sys.executable and '--cases' in c]
 samples={c[c.index('--cases')+1]:int(c[c.index('--repeats')+1]) for c in client}
 manifest=json.loads((output/'source-manifest.json').read_text())
 snapshots_ok=all(hashlib.sha256((output/'sources'/f).read_bytes()).hexdigest()==sha for f,sha in manifest.items())
 check={'ended_status_persisted':bool(state.get('ended_utc')),'source_snapshots_match_manifest':snapshots_ok,
        'only_this_created_container_cleaned':all(c[-1] in (created_name,cid) for c in cleanup),
        'watcher_joined':['mock_watcher_join'] in events,'clock_terminated':['mock_clock_terminate'] in events,
        'final_service_check_called':verify_calls[-1]=='runs/'+label+'/services-after.json'}
 if kind=='measure_success_retained':
  check.update(status_completed=state['state']=='completed',retained_exact_name=created_name=='pro6000d-qwen36-fp8-release',
       retained_metadata_correct=state.get('retained_service',{}).get('name')==created_name,
       no_stop_or_rm=not cleanup,mock_service_still_running=exists and running,
       one_b_arm=[r['arm'] for r in state['arms']]==['b'],samples_12_6_6=samples=={'prefill':12,'decode':6,'thinking':6})
 elif kind=='smoke_success_cleanup':
  check.update(status_completed=state['state']=='completed',stop_and_rm_called=[c[1] for c in cleanup]==['stop','rm'],
       mock_service_removed=not exists and not running,no_retained_service='retained_service' not in state,
       samples_1_1=samples=={'prefill':1,'decode':1})
 else:
  check.update(status_failed=state['state']=='failed',error_recorded=state.get('error_type')=='RuntimeError',
       stop_and_rm_called=[c[1] for c in cleanup]==['stop','rm'],mock_service_removed=not exists and not running,
       no_retained_service='retained_service' not in state,stopped_after_second_client=samples=={'prefill':12,'decode':6})
 print('CPU_MOCK_RESULT '+json.dumps({'case':kind,'passed':all(check.values()),'checks':check,'state':state,
       'cleanup_commands':cleanup,'client_repeats':samples,'created_name':created_name,
       'mock_container_exists_after_case':exists,'mock_container_running_after_case':running,
       'verify_calls':verify_calls,'source_manifest':manifest}),flush=True)
m.run(types.SimpleNamespace(label=label,stage=stage,image=image,extra_env=[]))
